(647969, 67772, 17200, '<td valign="top">heh heh, nice pose</td>', 'heh heh, nice pose', '2004-04-01 11:36:21.000000', NULL, 1),
(647970, 67137, 4285, '<td valign="top">Great capture but focus is a little soft. Maybe a touch of USM might help marginally.</td>', 'Great capture but focus is a little soft. Maybe a touch of USM might help marginally.', '2004-04-01 11:36:28.000000', NULL, 1),
