(648431, 67248, 327, '<td valign="top">Good work. This is very nice. Food Magazine. :)</td>', 'Good work. This is very nice. Food Magazine. :)', '2004-04-01 14:18:28.000000', NULL, 1),
(648432, 65355, 11897, '<td valign="top">a stunner, what can I say, 10 points.</td>', 'a stunner, what can I say, 10 points.', '2004-04-01 14:18:32.000000', NULL, 1),
(648433, 67794, 13897, '<td valign="top">Great shot. This is my highest ranked image. I think this would win the motion blur contest too.</td>', 'Great shot. This is my highest ranked image. I think this would win the motion blur contest too.', '2004-04-01 14:18:37.000000', NULL, 1),
