(648462, 67355, 14603, '<td valign="top">great image with excellent composition and exposure...9</td>', 'great image with excellent composition and exposure...9', '2004-04-01 14:37:08.000000', NULL, 1),
(648463, 66986, 17720, '<td valign="top">I''m rather jealous of your available landscapes.  If only all DPCers could live in Wales.  10.</td>', 'I''m rather jealous of your available landscapes.  If only all DPCers could live in Wales.  10.', '2004-04-01 14:38:39.000000', NULL, 1),
(648464, 66917, 14476, '<td valign="top">This was a tough shot to get and you did a fine job on it.  Good luck.</td>', 'This was a tough shot to get and you did a fine job on it.  Good luck.', '2004-04-01 14:38:56.000000', NULL, 1),
