INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(650811, 67429, 259, '<td valign="top">while some may think you''ve gone into digital art, i like it.  the crop, composition, and coloring are all pluses.</td>', 'while some may think you''ve gone into digital art, i like it.  the crop, composition, and coloring are all pluses.', '2004-04-02 17:46:04.000000', NULL, 1),
(650825, 66448, 3599, '<td valign="top">Maybe vertical composition instead of horizontal here?  I''d like to either see the guy in relation to how far off the water he is or maybe him and the kite.  Great colors and capture though.</td>', 'Maybe vertical composition instead of horizontal here?  I''d like to either see the guy in relation to how far off the water he is or maybe him and the kite.  Great colors and capture though.', '2004-04-02 18:00:38.000000', NULL, 1),
(650871, 66539, 14614, '<td valign="top">I like your pov here... got me to take a more detailed look.  Seems to me you''ve set the stage but you need a main subject  (your title says the end but the pointy end is oof and so is the tall end)</td>', 'I like your pov here... got me to take a more detailed look.  Seems to me you''ve set the stage but you need a main subject  (your title says the end but the pointy end is oof and so is the tall end)', '2004-04-02 18:40:23.000000', NULL, 1),
(650873, 67736, 10720, '<td valign="top">likes - creative idea, very colorful, good white balance and dof<br/>dislikes, no single central point of interest. hot spot on the right hand side, different sized green triangles in the corner<br/>5</td>', 'likes - creative idea, very colorful, good white balance and dofdislikes, no single central point of interest. hot spot on the right hand side, different sized green triangles in the corner5', '2004-04-02 18:40:38.000000', NULL, 1),
(650876, 64270, 10720, '<td valign="top">It is one of those wow shots - 10 <br/>maybe a tiny bit wider DOF would help with his back legs.</td>', 'It is one of those wow shots - 10 maybe a tiny bit wider DOF would help with his back legs.', '2004-04-02 18:41:39.000000', NULL, 1),
(650877, 67800, 14614, '<td valign="top">Like how your subject''s head is tilted to catch the light (but got her hand over exposed as well as the lamp) the composition is a bit too busy and doesn''t tell the story as well.</td>', 'Like how your subject''s head is tilted to catch the light (but got her hand over exposed as well as the lamp) the composition is a bit too busy and doesn''t tell the story as well.', '2004-04-02 18:41:51.000000', NULL, 1),
