(651524, 67791, 6630, '<td valign="top">Beautiful colors.</td>', 'Beautiful colors.', '2004-04-03 09:20:15.000000', NULL, 1),
(651530, 66148, 6630, '<td valign="top">Beautiful</td>', 'Beautiful', '2004-04-03 09:23:50.000000', NULL, 1),
