(657409, 64270, 6130, '<td valign="top">Lovely 10.</td>', 'Lovely 10.', '2004-04-07 13:54:29.000000', NULL, 1),
(657410, 67546, 13336, '<td valign="top">it looks starnge the way most of the trees are a vibrant green but the tops are all gray.  i''m not sure if its natural or an editing effect, but it is a little starnge to look at nevertheless.  the lightbeams are gorgeous!</td>', 'it looks starnge the way most of the trees are a vibrant green but the tops are all gray.  i''m not sure if its natural or an editing effect, but it is a little starnge to look at nevertheless.  the lightbeams are gorgeous!', '2004-04-07 13:55:05.000000', NULL, 1),
(657415, 66917, 6130, '<td valign="top">So good.10.</td>', 'So good.10.', '2004-04-07 13:56:10.000000', NULL, 1),
(657422, 64942, 8610, '<td valign="top">A bit tilted.. Good idea, and strange sky. Why is the sky so strange?</td>', 'A bit tilted.. Good idea, and strange sky. Why is the sky so strange?', '2004-04-07 13:57:31.000000', NULL, 1),
