(657814, 65003, 3569, '<td valign="top">Nice bird, I would have cropped a bit tighter to bring your eye into the bird better.</td>', 'Nice bird, I would have cropped a bit tighter to bring your eye into the bird better.', '2004-04-07 15:44:26.000000', NULL, 1),
(657819, 67365, 3569, '<td valign="top">The path leads the eye off the page, next time move to where the path will keep your eye in the photo.  Just my opinion.</td>', 'The path leads the eye off the page, next time move to where the path will keep your eye in the photo.  Just my opinion.', '2004-04-07 15:45:34.000000', NULL, 1),
